/* Additional cards used by the current teaching examples; 2020 SP1 QRG. */
(() => {
 const entries=window.InputCatalog.entries;
 const f=(label,help)=>({label,help});
 function fixed(id,title,category,summary,page,rows,definitions,notes=[]){
  const lines=definitions.map((defs,j)=>Array.from({length:10},(_,i)=>defs[i]?f(...defs[i]):f(i===9?'継続':'未使用',i===9?'次行を続ける場合は継続識別子を記述します。最終行では空欄です。':'この書式では使用しない欄です。空欄のまま保持します。')));
  entries.push({key:id,id,title,family:'bulk',category,summary,page,rows,lines,kind:'fixed',notes});
 }
 const sid=['SID','正整数のセット番号。Case Controlまたは他のカードから、この番号で選択します。'];
 fixed('RLOAD2','振幅・位相による周波数荷重','動荷重','周波数に対する振幅Bと位相φを指定し、空間分布Aに掛けて複素荷重を定義します。時間遅れと位相進みも別に指定できます。',3065,[['RLOAD2','500','600','','','310']],[
  [['カード名','RLOAD2。'],sid,['EXCITEID','荷重の空間分布。DAREA、静荷重セット、LSEQのEXCITEID、強制運動のSPCDなどを参照します。TYPEとの対応を確認します。'],['DELAY','整数はDELAYのSID、実数は全加振自由度に共通の時間遅れ。空欄は遅れ0です。整数1と実数1.は意味が異なります。'],['DPHASE','整数はDPHASEのSID、実数は共通の位相進み［度］。空欄は0°。負値は位相遅れです。'],['TB / RB','整数は振幅関数TABLEDiのTID、非ゼロ実数は一定振幅倍率。例の310はテーブル番号です。'],['TP / RP','整数は位相関数TABLEDiのTID、実数は一定の位相［度］。空欄は0°です。'],['TYPE','0またはLOAD：荷重。1/DISP：強制変位、2/VELO：強制速度、3/ACCE：強制加速度。空欄は0。強制運動は対応するSPCDと拘束設定が必要です。']]
 ],['同じSIDのDLOADが選択する動荷重成分として用います。表のXは周波数、位相の単位は度です。']);
 fixed('TLOAD2','式で与える過渡荷重','動荷重','指定期間だけ作用する正弦波、指数・べき乗包絡の荷重を定義します。時間依存倍率と空間分布を分けて指定します。',3302,[['TLOAD2','200','300','','0','0.','.01','200.','-90.','+T'],['+T','0.','0.']],[
  [['カード名','TLOAD2。'],sid,['EXCITEID','DAREA、静荷重またはLSEQのEXCITEID、SPCDなどで定義した空間分布の参照番号。'],['DELAY','整数はDELAYのSID、実数は共通の遅れ時間τ。空欄は0。'],['TYPE','0/LOADは荷重、1/DISP・2/VELO・3/ACCEは強制運動。空欄は0。'],['T1','荷重開始時刻の基準。実際の作用開始はT1＋τ。この例は0.です。'],['T2','作用終了時刻の基準。T2>T1。実際の終了はT2＋τ。'],['F','単位時間あたりの周期数。秒を使う場合Hz。既定0。'],['P','余弦関数の位相［度］。−90°で正弦波型、＋90°はその逆符号。既定0。'],['継続','この例は+Tで2行目へ接続します。']],
  [['継続','前行の+Tに一致。'],['C','指数包絡の係数。exp(C t̃)を掛けます。単位は1/時間、既定0。'],['B','べき乗包絡の指数。t̃のB乗を掛けます。既定0。'],['US0','強制運動に使用する初期変位の倍率。既定0。'],['VS0','強制運動に使用する初期速度の倍率。既定0。']]
 ],['t̃=t−T1−τ。T1＋τからT2＋τの外側では荷重は0です。','QRG PDF3305 Remark18に、2005以前の版との時刻評価差が記載されています。旧教材の時刻歴と比較するときは必ず確認します。']);
 fixed('LSEQ','静荷重分布の動荷重への接続','動荷重','静荷重セットを動荷重の空間分布番号に対応付けます。Case ControlのLOADSETで選択します。',2225,[['LSEQ','100','300','400']],[
  [['カード名','LSEQ。'],sid,['EXCITEID','RLOADi / TLOADiから参照する空間分布の識別番号。例では300。'],['LID','PLOAD2、FORCE等の静荷重セット番号。例ではPLOAD2のSID=400。空欄では機械的静荷重を追加しません。'],['TID','熱荷重用の温度セット番号。空欄では温度荷重を追加しません。通常モデルではLIDとTIDの両方を空欄にはできません。']]
 ],['LOADSETを用いない方式では、静荷重のSIDを動荷重のEXCITEIDから直接参照できる場合があります。この例ではLOADSET/LSEQで静荷重分布を明示的に接続します。']);
 for(const [id,label,page,value] of [['DELAY','時間遅れ',1749,'.005'],['DPHASE','位相進み',1794,'-30.']]){
  const unit=id==='DELAY'?'モデルの時間単位による遅れ時間。秒を使う例では0.005は5 ms。':'位相進み［度］。−30.は30°の遅れ。';
  fixed(id,'動荷重の'+label,'動荷重','加振点・成分ごとの'+label+'を定義します。単独では荷重を作りません。',page,[[id,'610','11','3',value]],[
   [['カード名',id+'。'],sid,['P1','加振するGRIDまたはスカラ点のID。'],['C1','GRIDでは成分1～6、スカラ点では0または空欄。荷重の成分に一致させます。'],[id==='DELAY'?'T1':'TH1',unit],['P2','同じ行で2点目を指定できます。1点だけなら空欄。'],['C2','2点目の成分。P2を指定しない場合は空欄。'],[id==='DELAY'?'T2':'TH2','2点目の'+label+'。P2を指定しない場合は空欄。']]
  ]);
 }
 fixed('FREQ4','固有振動数の周辺を細分化','固有値・周波数・時間設定','モーダル周波数応答で、各固有振動数の周辺へ加振周波数を追加します。FREQ1などと同じSIDを使うと周波数集合を合成します。',2047,[['FREQ4','100','10.','800.','.025','5']],[
  [['カード名','FREQ4。'],sid,['F1','対象周波数範囲の下限［cycles/時間］。既定0。'],['F2','上限。F2>F1、既定1.0E20。'],['FSPD','各固有振動数fₙに対する広がりの割合。例は±2.5%。0<FSPD<1、既定0.1。'],['NFM','各帯域内に等間隔で作る点数。正整数、既定3。偶数を指定すると1を加えた奇数になります。']]
 ],['SOL111等のモーダル周波数応答用。直接周波数応答では無視されます。','F1～F2の境界により生成周波数が除外される場合があります。共振付近では減衰も設定します。']);
 fixed('PARAM_COUPMASS','質量行列の形式','質量・単位','COUPMASS>0で対応要素の連成質量行列、負値（既定−1）で集中質量行列を選びます。密度や単位換算の指定ではありません。',837,[['PARAM','COUPMASS','1']],[
  [['カード名','PARAM。'],['N','COUPMASS。'],['V1','整数。正値は対応要素の連成質量行列を要求。負値は集中質量行列。この例では1を指定します。']]
 ]);
 const p=entries.find(e=>e.key==='PARAM_COUPMASS');p.id='PARAM / COUPMASS';p.family='parameter';
 entries.push({key:'CASE_LOADSET',id:'LOADSET',title:'静荷重分布セットの選択',family:'case',category:'動解析条件',kind:'control',summary:'動荷重等で利用するLSEQのセットを選択します。DLOADで選ぶ時間・周波数依存荷重とは役割が異なります。',syntax:'LOADSET = n',example:'SUBCASE 1\n  DLOAD = 700\n  LOADSET = 100',location:'Case Control（CENDとBEGIN BULKの間）',terms:[['n','正整数。選択するLSEQのSID。'],['指定位置','複数SUBCASEを使う動解析では、最初のSUBCASEまたは全SUBCASEの上に指定します。']],page:474,notes:['LSEQのEXCITEIDをRLOADi/TLOADiが参照し、LIDが静荷重セットを参照します。番号の役割を区別します。']});
})();
